\frac{t}{q} &= \frac{(2s)}{9r} \\
&= \left( \frac{s}{r} \right) \left( \frac{2}{9} \right) \\
&= (6) \left( \frac{2}{9} \right) \\
\frac{t}{q} &= \boxed{\frac{4}{3}}
\end{align*}
